    ...

widget.solution:
def log_diff(log_a, log_b):
    out = []
    for k in set(log_a) | set(log_b):
        if k in ("run", "events"):
            continue
        a, b = log_a.get(k, "<missing>"), log_b.get(k, "<missing>")
        if isinstance(a, dict) and isinstance(b, dict):
            for j in set(a) | set(b):
                if a.get(j, "<missing>") != b.get(j, "<missing>"):
                    out.append(k + "." + j)
        elif a != b:
            out.append(k)
    return sorted(out)

